def max_path(values):
    best = float("-inf")

    def visit(i):
        nonlocal best             # needed because we reassign best
        best = max(best, values[i])

    found = []
    def collect(x):
        found.append(x)           # mutation: no nonlocal needed

    for i in range(len(values)):
        visit(i)
        collect(values[i])
    return best, found

print(max_path([3, 8, 2]))

