def solve(nums, target):
    seen = {}                      # value -> index (or count, or list)
    for i, x in enumerate(nums):
        if target - x in seen:     # look up what you need
            return [seen[target - x], i]
        seen[x] = i                # record what you've seen

def solve(nums, target):
    nums.sort()
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        s = nums[lo] + nums[hi]
        if s == target:
            return [lo, hi]
        if s < target:
            lo += 1        # need bigger
        else:
            hi -= 1        # need smaller

def longest(s):
    window = {}
    left = best = 0
    for right, ch in enumerate(s):
        window[ch] = window.get(ch, 0) + 1        # expand
        while window[ch] > 1:                     # invalid? shrink
            window[s[left]] -= 1
            left += 1
        best = max(best, right - left + 1)        # record
    return best

def balanced(s):
    pairs = {")": "(", "]": "["}
    stack = []
    for c in s:
        if c in pairs:
            if not stack or stack.pop() != pairs[c]:
                return False
        else:
            stack.append(c)
    return not stack

def first_true(lo, hi, ok):
    # smallest x in [lo, hi] with ok(x) True (ok is monotonic)
    while lo < hi:
        mid = (lo + hi) // 2
        if ok(mid):
            hi = mid          # mid might be the answer
        else:
            lo = mid + 1      # answer is to the right
    return lo

def reverse(head):
    prev, cur = None, head
    while cur:
        nxt = cur.next      # save before overwriting
        cur.next = prev
        prev, cur = cur, nxt
    return prev

def middle(head):
    slow = fast = head
    while fast and fast.next:
        slow, fast = slow.next, fast.next.next
    return slow

def dfs(node):
    if not node:
        return 0                     # base case
    left = dfs(node.left)
    right = dfs(node.right)
    # combine: what does this subtree report to its parent?
    return 1 + max(left, right)

class Trie:
    def __init__(self):
        self.root = {}

    def insert(self, word):
        node = self.root
        for c in word:
            node = node.setdefault(c, {})
        node["$"] = True            # end-of-word marker

    def starts_with(self, prefix):
        node = self.root
        for c in prefix:
            if c not in node:
                return False
            node = node[c]
        return True

import heapq

def k_largest(nums, k):
    heap = []
    for x in nums:
        heapq.heappush(heap, x)
        if len(heap) > k:
            heapq.heappop(heap)    # drop the smallest
    return heap                    # the k largest

def combos(candidates, target):
    out, path = [], []
    def bt(start, remaining):
        if remaining == 0:
            out.append(path[:])           # copy!
            return
        for i in range(start, len(candidates)):
            if candidates[i] <= remaining:
                path.append(candidates[i])          # choose
                bt(i, remaining - candidates[i])    # explore
                path.pop()                          # un-choose
    bt(0, target)
    return out

from collections import deque

def bfs(start, neighbors):
    seen = {start}
    q = deque([start])
    while q:
        node = q.popleft()
        for nxt in neighbors(node):
            if nxt not in seen:
                seen.add(nxt)          # mark when enqueued
                q.append(nxt)
    return seen

from collections import deque

def topo_order(nodes, edges):
    graph = {n: [] for n in nodes}
    indeg = {n: 0 for n in nodes}
    for a, b in edges:
        graph[a].append(b)
        indeg[b] += 1
    q = deque(n for n in nodes if indeg[n] == 0)
    order = []
    while q:
        n = q.popleft()
        order.append(n)
        for m in graph[n]:
            indeg[m] -= 1
            if indeg[m] == 0:
                q.append(m)
    return order if len(order) == len(nodes) else None   # None = cycle

def rob(nums):
    # dp[i] = best using the first i houses
    prev2 = prev1 = 0
    for x in nums:
        prev2, prev1 = prev1, max(prev1, prev2 + x)
    return prev1

def lcs(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if a[i] == b[j]:
                dp[i][j] = 1 + dp[i + 1][j + 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])
    return dp[0][0]

def max_subarray(nums):
    best = cur = nums[0]
    for x in nums[1:]:
        cur = max(x, cur + x)   # extend or restart
        best = max(best, cur)
    return best

def merge(intervals):
    out = []
    for s, e in sorted(intervals):
        if out and s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)   # overlap -> extend
        else:
            out.append([s, e])
    return out

def rotate(m):
    n = len(m)
    for i in range(n):
        for j in range(i + 1, n):
            m[i][j], m[j][i] = m[j][i], m[i][j]   # transpose
    for row in m:
        row.reverse()                              # mirror

def count_ones(n):
    count = 0
    while n:
        n &= n - 1     # drop lowest set bit
        count += 1
    return count
